  { id: 7, question: "In Washington state, what is the speed limit in school zones when children are present?", options: ["15 mph", "20 mph", "25 mph", "30 mph"], correct: 1, explanation: "Washington sets school zone speed limits at 20 mph when children are present or when the flashing lights are active." },
  { id: 8, question: "In Washington state, what is the maximum speed limit on interstate highways?", options: ["60 mph", "65 mph", "70 mph", "75 mph"], correct: 2, explanation: "The maximum posted speed limit on Washington state interstate highways is 70 mph in rural areas." },
  { id: 9, question: "In Washington state, the minimum liability insurance requirements are:", options: ["15/30/10", "25/50/10", "25/50/25", "30/60/25"], correct: 1, explanation: "Washington requires minimum liability insurance of $25,000 per person/$50,000 per accident for bodily injury and $10,000 for property damage (25/50/10)." },
  { id: 10, question: "In Washington state, using a handheld cell phone while driving is:", options: ["Legal if under 5 seconds", "A secondary offense", "A primary offense with a fine", "Legal at red lights"], correct: 2, explanation: "Washington state prohibits using handheld cell phones while driving, and it is a primary offense meaning officers can pull you over solely for this violation." },
  { id: 11, question: "In Washington state, the DUI offense is referred to as:", options: ["DWI", "OUI", "DUI", "OWI"], correct: 2, explanation: "Washington state refers to impaired driving as DUI (Driving Under the Influence)." },
  { id: 12, question: "In Washington state, what is the implied consent law regarding chemical testing?", options: ["You can always refuse without penalty", "Refusal results in automatic license revocation for at least 1 year", "There is no implied consent law", "Refusal results in a fine only"], correct: 1, explanation: "Washington's implied consent law means refusing a chemical test results in automatic license revocation for at least one year." },
  { id: 13, question: "In Washington state, the nighttime driving restriction for intermediate license holders under 18 is:", options: ["10 pm to 5 am", "Midnight to 5 am", "1 am to 5 am", "9 pm to 5 am"], correct: 0, explanation: "Washington intermediate license holders under 18 cannot drive between 1 am and 5 am for the first 6 months, then 1 am to 5 am ongoing." },
  { id: 14, question: "In Washington state, for the first 6 months of an intermediate license, passengers are limited to:", options: ["No passengers", "Immediate family members only", "One passenger under 20 who is not family", "Up to 3 passengers"], correct: 0, explanation: "For the first 6 months, Washington intermediate license holders under 18 may not carry passengers under 20 who are not immediate family members." },
  { id: 15, question: "In Washington state, how long must you hold an instruction permit before getting an intermediate license?", options: ["3 months", "6 months", "9 months", "12 months"], correct: 1, explanation: "Washington requires you to hold an instruction permit for at least 6 months before being eligible for an intermediate license." },
  { id: 16, question: "In Washington state, the Move Over law requires drivers to:", options: ["Only slow down", "Change lanes or slow down when passing stopped emergency or maintenance vehicles", "Stop completely", "Flash headlights"], correct: 1, explanation: "Washington's Move Over law requires drivers to change lanes if possible or reduce speed when approaching stopped emergency, tow, or maintenance vehicles with flashing lights." },
  { id: 17, question: "In Washington state, what is the speed limit on city streets unless otherwise posted?", options: ["20 mph", "25 mph", "30 mph", "35 mph"], correct: 1, explanation: "The default speed limit on Washington city streets is 25 mph unless otherwise posted." },
  { id: 18, question: "In Washington state, what is the speed limit on county roads unless otherwise posted?", options: ["25 mph", "35 mph", "45 mph", "50 mph"], correct: 1, explanation: "Washington county roads have a default speed limit of 35 mph when not posted." },
  { id: 19, question: "In Washington state, you must stop for a school bus with flashing red lights:", options: ["Only if on the same side of the road", "From both directions unless separated by a physical barrier", "Only in school zones", "Only during school hours"], correct: 1, explanation: "In Washington, you must stop for a school bus with flashing red lights from both directions unless separated by a physical barrier or separate roadways." },
  { id: 20, question: "In Washington state, the fine for a first DUI conviction can include:", options: ["Up to $500", "Up to $5,000", "Up to $10,000", "Up to $25,000"], correct: 1, explanation: "A first DUI conviction in Washington can include fines up to $5,000, plus mandatory jail time." },
  { id: 21, question: "In Washington state, when driving in fog you should use:", options: ["High beams", "Low beams", "Parking lights only", "No lights"], correct: 1, explanation: "In Washington, you should use low beams in fog, as high beams reflect off fog and reduce visibility." },
  { id: 22, question: "In Washington state, you must turn on headlights:", options: ["Only at night", "From 30 minutes after sunset to 30 minutes before sunrise and in low visibility", "Only in rain", "Only on highways"], correct: 1, explanation: "Washington requires headlights from 30 minutes after sunset to 30 minutes before sunrise and during conditions of low visibility." },
  { id: 23, question: "In Washington state, the penalty for vehicular homicide while DUI is:", options: ["A misdemeanor", "A gross misdemeanor", "A Class A felony", "A Class B felony"], correct: 2, explanation: "Vehicular homicide while under the influence in Washington is a Class A felony, carrying severe penalties." },
  { id: 24, question: "In Washington state, you must report a vehicle collision to law enforcement if:", options: ["Any damage occurs", "There is injury, death, or apparent damage exceeding $800", "Only if someone is injured", "Only if the vehicle cannot be driven"], correct: 1, explanation: "Washington law requires reporting a collision to law enforcement if there is injury, death, or apparent property damage over $800." },
  { id: 25, question: "In Washington state, which of the following is true about roundabouts?", options: ["Vehicles inside the roundabout must yield", "Vehicles entering the roundabout must yield to traffic already in it", "You must stop before entering", "You may change lanes inside the roundabout"], correct: 1, explanation: "In Washington, vehicles entering a roundabout must yield to traffic already circulating within it." },
  { id: 26, question: "In Washington state, what is the minimum age to get a full (unrestricted) driver license?", options: ["16", "17", "18", "21"], correct: 2, explanation: "In Washington, drivers can obtain a full unrestricted driver license at age 18." },
  { id: 27, question: "In Washington state, what happens to your license if you accumulate too many traffic violations?", options: ["You receive a warning letter", "Your license may be suspended under the habitual traffic offender law", "Nothing until a DUI", "You must retake the written test"], correct: 1, explanation: "Washington can suspend your license under the habitual traffic offender law if you accumulate too many violations." },
  { id: 28, question: "In Washington state, you must yield to pedestrians:", options: ["Only at marked crosswalks", "At all marked and unmarked crosswalks", "Only when a crossing guard is present", "Only at intersections with signals"], correct: 1, explanation: "Washington law requires drivers to yield to pedestrians at all crosswalks, both marked and unmarked." },
  { id: 29, question: "In Washington state, motorcyclists are allowed to:", options: ["Lane split in slow traffic", "Ride between lanes", "Share a lane with another motorcycle", "Ride on the shoulder"], correct: 2, explanation: "Washington allows two motorcyclists to share a single lane side by side, but lane splitting (riding between lanes of traffic) is not permitted." },
  { id: 30, question: "In Washington state, you may make a U-turn:", options: ["Anywhere that is safe", "Only at intersections where it is not prohibited", "Never on any road", "Only in parking lots"], correct: 1, explanation: "In Washington, U-turns are allowed at intersections unless posted otherwise, as long as they can be made safely." },
  { id: 31, question: "In Washington state, the speed limit on state highways outside city limits unless otherwise posted is:", options: ["45 mph", "50 mph", "55 mph", "60 mph"], correct: 3, explanation: "The default speed limit on Washington state highways outside city limits is 60 mph unless otherwise posted." },
  { id: 32, question: "In Washington state, how far ahead must you signal before turning?", options: ["50 feet", "100 feet", "150 feet", "200 feet"], correct: 1, explanation: "Washington law requires drivers to signal at least 100 feet before making a turn." },
  { id: 33, question: "In Washington state, children under what age must be in a child restraint device?", options: ["4 years old", "6 years old", "8 years old", "10 years old"], correct: 2, explanation: "Washington law requires all children under 8 years old to be properly secured in an appropriate child restraint device." },
  { id: 34, question: "In Washington state, the penalty for driving with a suspended license is:", options: ["A civil infraction only", "A misdemeanor or gross misdemeanor", "A warning", "A $50 fine"], correct: 1, explanation: "Driving with a suspended license in Washington is a misdemeanor or gross misdemeanor depending on the reason for suspension." },
  { id: 35, question: "In Washington state, when driving through a highway work zone, fines for traffic violations are:", options: ["The same as normal", "Doubled", "Tripled", "Quadrupled"], correct: 1, explanation: "Washington doubles fines for traffic violations committed in highway work zones when workers are present." },
  { id: 36, question: "In Washington state, what blood alcohol level for a commercial driver is considered DUI?", options: ["0.02%", "0.04%", "0.06%", "0.08%"], correct: 1, explanation: "Commercial drivers in Washington are held to a lower BAC standard of 0.04%." },
  { id: 37, question: "In Washington state, it is illegal to pass a vehicle on the right by driving off the pavement.", options: ["True, it is always illegal", "False, it is always legal", "Only illegal on highways", "Legal if the shoulder is paved"], correct: 0, explanation: "In Washington, it is illegal to pass another vehicle on the right by driving off the pavement or main portion of the roadway." },
  { id: 38, question: "In Washington state, when parallel parking on a hill facing uphill with a curb, you should turn your wheels:", options: ["Straight ahead", "Toward the curb", "Away from the curb", "It does not matter"], correct: 2, explanation: "In Washington, when parking uphill with a curb, turn your front wheels away from the curb so the vehicle rolls into the curb if it moves." },
  { id: 39, question: "In Washington state, the intermediate license driving restriction at night is lifted when the driver turns:", options: ["16.5 years old", "17 years old", "18 years old", "21 years old"], correct: 2, explanation: "In Washington, nighttime driving restrictions for intermediate license holders are lifted when the driver turns 18." },
  { id: 40, question: "In Washington state, texting while driving is classified as:", options: ["A secondary offense", "A primary offense subject to a fine", "A warning-only offense", "Legal if stopped at a light"], correct: 1, explanation: "Texting while driving in Washington is a primary offense, and officers can stop you solely for this violation." }
