  { id: 20, question: "In Arizona, what is the speed limit on urban freeway/interstate highways?", options: ["55 mph", "60 mph", "65 mph", "70 mph"], correct: 2, explanation: "Urban freeway and interstate speed limits in Arizona are typically 65 mph." },
  { id: 21, question: "In Arizona, what color curb marking indicates no stopping, standing, or parking?", options: ["White", "Yellow", "Red", "Blue"], correct: 2, explanation: "In Arizona, red curb markings indicate no stopping, standing, or parking at any time." },
  { id: 22, question: "In Arizona, you must use your headlights from:", options: ["Sunset to sunrise", "30 minutes after sunset to 30 minutes before sunrise", "Dusk to dawn", "Only when visibility is less than 500 feet"], correct: 0, explanation: "Arizona requires headlights from sunset to sunrise and during periods of insufficient light." },
  { id: 23, question: "In Arizona, how close to a fire hydrant is it illegal to park?", options: ["10 feet", "15 feet", "20 feet", "25 feet"], correct: 1, explanation: "In Arizona, it is illegal to park within 15 feet of a fire hydrant." },
  { id: 24, question: "In Arizona, graduated license holders are limited to how many passengers under 18 who are not family for the first 6 months?", options: ["0 passengers", "1 passenger", "2 passengers", "No limit"], correct: 1, explanation: "Arizona graduated license holders may carry no more than 1 passenger under 18 who is not an immediate family member for the first 6 months." },
  { id: 25, question: "In Arizona, when approaching a school bus with flashing red lights, you must:", options: ["Slow to 15 mph", "Stop and remain stopped until the lights stop flashing", "Honk and pass carefully", "Proceed if on the opposite side of a divided highway"], correct: 1, explanation: "In Arizona, drivers must stop and remain stopped when a school bus displays flashing red lights, unless on the opposite side of a physically divided highway." },
  { id: 26, question: "In Arizona, what is the penalty for leaving the scene of an accident involving injury?", options: ["A misdemeanor", "A Class 5 felony", "A Class 3 felony", "No penalty if reported later"], correct: 2, explanation: "Leaving the scene of an accident involving injury in Arizona is a Class 3 felony, carrying severe penalties." },
  { id: 27, question: "In Arizona, child safety seat laws require children under what age to be in an approved safety seat?", options: ["4 years old", "5 years old", "8 years old", "10 years old"], correct: 2, explanation: "Arizona requires children under 8 years old to be properly secured in a child safety seat or booster seat unless they are 4 feet 9 inches or taller." },
  { id: 28, question: "In Arizona, what happens when you refuse a BAC test under implied consent?", options: ["Nothing", "Your license is suspended for 12 months", "You receive a warning", "You must take the test at the station"], correct: 1, explanation: "Refusing a BAC test in Arizona under the implied consent law results in automatic license suspension for 12 months." },
  { id: 29, question: "In Arizona, all driver license holders must update their photo every:", options: ["4 years", "8 years", "12 years", "Only at renewal"], correct: 2, explanation: "Although Arizona licenses do not expire until age 65, license holders must update their photo every 12 years." },
  { id: 30, question: "In Arizona, you must signal your intention to turn at least how many feet before turning?", options: ["50 feet", "100 feet", "150 feet", "200 feet"], correct: 1, explanation: "Arizona law requires drivers to signal at least 100 feet before turning." },
  { id: 31, question: "In Arizona, what is the speed limit on highways outside of urban areas that are not interstates?", options: ["45 mph", "55 mph", "60 mph", "65 mph"], correct: 3, explanation: "The speed limit on non-interstate highways outside urban areas in Arizona is typically 65 mph." },
  { id: 32, question: "In Arizona, the 'Stupid Motorist Law' applies when a driver:", options: ["Speeds in a school zone", "Drives around barricades into a flooded roadway", "Runs a red light", "Fails to yield to pedestrians"], correct: 1, explanation: "Arizona's unique 'Stupid Motorist Law' holds drivers financially responsible for rescue costs if they drive around barricades into a flooded road." },
  { id: 33, question: "In Arizona, what type of vehicle emissions testing is required in the Phoenix and Tucson metro areas?", options: ["No emissions testing required", "Annual emissions testing for vehicles in Area A and Area B", "Only commercial vehicles", "Only vehicles over 10 years old"], correct: 1, explanation: "Arizona requires annual emissions testing for vehicles registered in the Phoenix (Area A) and Tucson (Area B) metro areas." },
  { id: 34, question: "In Arizona, it is illegal to drive the wrong way on a highway. The penalty can be:", options: ["A civil infraction", "A class 1 misdemeanor", "A class 6 felony", "A warning"], correct: 2, explanation: "Driving the wrong way on a highway in Arizona is a serious offense that can be charged as a class 6 felony." },
  { id: 35, question: "In Arizona, when must you yield to a funeral procession?", options: ["Only at intersections", "Never, they have no special rights", "Always, unless directed by law enforcement", "Only if they have a police escort"], correct: 2, explanation: "In Arizona, drivers must yield the right-of-way to funeral processions." },
  { id: 36, question: "In Arizona, the speed limit in alleys is:", options: ["10 mph", "15 mph", "20 mph", "25 mph"], correct: 1, explanation: "The speed limit in Arizona alleys is 15 mph." },
  { id: 37, question: "In Arizona, an ignition interlock device is required for:", options: ["Only repeat DUI offenders", "All DUI convictions including first offense", "Only Extreme DUI convictions", "Only Super Extreme DUI convictions"], correct: 1, explanation: "Arizona requires ignition interlock devices for all DUI convictions, including first offenses." },
  { id: 38, question: "In Arizona, what must you do when you see a dust storm (haboob) while driving?", options: ["Speed up to escape it", "Pull off the road, stop, turn off lights, take foot off brake", "Continue at reduced speed", "Turn on high beams"], correct: 1, explanation: "During a dust storm in Arizona, you should pull off the road, stop, turn off your lights, and take your foot off the brake to avoid rear-end collisions." },
  { id: 39, question: "In Arizona, after age 65, how often must you renew your driver license?", options: ["Every 2 years", "Every 5 years", "Every 10 years", "Every year"], correct: 1, explanation: "After age 65, Arizona requires driver license renewal every 5 years." },
  { id: 40, question: "In Arizona, seat belt use is enforced as what type of law?", options: ["Primary enforcement law", "Secondary enforcement law", "No seat belt law exists", "Primary for front seat, secondary for rear"], correct: 1, explanation: "Arizona enforces seat belt use as a secondary offense, meaning officers must have another reason to stop you before citing for a seat belt violation." }
