  { id: 9, question: "In Massachusetts, what is the maximum speed limit on interstate highways?", options: ["55 mph", "60 mph", "65 mph", "70 mph"], correct: 2, explanation: "The maximum speed limit on Massachusetts interstate highways is 65 mph." },
  { id: 10, question: "In Massachusetts, using a handheld cell phone while driving is:", options: ["Legal for adults", "A primary offense for all drivers", "A secondary offense", "Only illegal for those under 18"], correct: 1, explanation: "Massachusetts enacted a hands-free law making any handheld use of electronic devices while driving a primary offense for all drivers." },
  { id: 11, question: "In Massachusetts, Junior Operator License holders are prohibited from:", options: ["Driving on highways", "Using any cell phone including hands-free", "Driving at night at all", "Carrying any passengers"], correct: 1, explanation: "Massachusetts prohibits Junior Operator License holders (under 18) from using any mobile phone, including hands-free, while driving." },
  { id: 12, question: "In Massachusetts, what are the minimum auto insurance requirements?", options: ["20/40/5", "25/50/25", "15/30/10", "20/40/10"], correct: 0, explanation: "Massachusetts requires minimum auto insurance of $20,000 per person/$40,000 per accident for bodily injury and $5,000 for property damage (20/40/5)." },
  { id: 13, question: "In Massachusetts, what is unique about auto insurance compared to other states?", options: ["Insurance is optional", "It uses a merit rating system affecting premiums", "There is no-fault insurance only", "The state provides free insurance"], correct: 1, explanation: "Massachusetts uses a merit rating system where at-fault accidents and traffic violations affect insurance premiums." },
  { id: 14, question: "In Massachusetts, a Junior Operator may not carry passengers under 18 for the first:", options: ["3 months", "6 months", "9 months", "12 months"], correct: 1, explanation: "Massachusetts Junior Operators cannot carry passengers under 18 who are not immediate family members for the first 6 months." },
  { id: 15, question: "In Massachusetts, how many supervised driving hours are required before getting a JOL?", options: ["30 hours", "40 hours", "50 hours", "60 hours"], correct: 1, explanation: "Massachusetts requires a minimum of 40 hours of supervised driving practice, including night driving, before obtaining a Junior Operator License." },
  { id: 16, question: "In Massachusetts, the speed limit in a school zone is:", options: ["15 mph", "20 mph", "25 mph", "30 mph"], correct: 1, explanation: "Massachusetts school zones have a speed limit of 20 mph when children are present." },
  { id: 17, question: "In Massachusetts, the Move Over law requires drivers to:", options: ["Stop completely for all emergency vehicles", "Move over or slow down for stopped emergency and maintenance vehicles", "Only slow down", "Move over only for police"], correct: 1, explanation: "Massachusetts Move Over law requires drivers to move over one lane or, if not possible, slow down when approaching stopped emergency, maintenance, or tow vehicles with flashing lights." },
  { id: 18, question: "In Massachusetts, the first offense for refusing a breathalyzer results in license suspension for:", options: ["90 days", "180 days", "1 year", "3 years"], correct: 1, explanation: "In Massachusetts, refusing a breathalyzer test for the first time results in an automatic 180-day license suspension." },
  { id: 19, question: "In Massachusetts, what is Melanie's Law?", options: ["A law requiring seat belts for all passengers", "A law that increased penalties for repeat OUI offenders", "A law banning texting while driving", "A law requiring child safety seats"], correct: 1, explanation: "Melanie's Law in Massachusetts significantly increased penalties for repeat OUI offenders, including mandatory ignition interlock devices and longer license suspensions." },
  { id: 20, question: "In Massachusetts, how long must you hold a learner's permit before getting a JOL?", options: ["3 months", "6 months", "9 months", "12 months"], correct: 1, explanation: "Massachusetts requires holding a learner's permit for at least 6 months before obtaining a Junior Operator License." },
  { id: 21, question: "In Massachusetts, the 'Right Turn on Red' rule applies:", options: ["At all intersections", "At all intersections unless a sign prohibits it, after a complete stop", "Only on one-way streets", "Never in Massachusetts"], correct: 1, explanation: "In Massachusetts, you may turn right on red after a complete stop unless a sign prohibits it. Note: in Boston, right on red was historically restricted at many intersections." },
  { id: 22, question: "In Massachusetts, what is the penalty for a first OUI conviction?", options: ["Fine only", "Up to $5,000 fine, up to 2.5 years in jail, 1-year license loss", "Warning and probation", "$1,000 fine only"], correct: 1, explanation: "A first OUI conviction in Massachusetts carries fines up to $5,000, up to 2.5 years in jail, and a 1-year license suspension." },
  { id: 23, question: "In Massachusetts, all passengers in a vehicle must wear seat belts. This is enforced as:", options: ["A primary law for all occupants", "A primary law for front seat, secondary for rear", "A secondary law", "No seat belt law exists"], correct: 0, explanation: "Massachusetts seat belt law is a primary enforcement law, meaning officers can stop and cite drivers solely for not wearing a seat belt." },
  { id: 24, question: "In Massachusetts, children must be in a child safety seat until:", options: ["Age 5 or 40 lbs", "Age 8 or 57 inches tall", "Age 6 or 60 lbs", "Age 10 or 4 feet 9 inches"], correct: 1, explanation: "Massachusetts requires children to use a child safety seat or booster seat until they are 8 years old or 57 inches (4 feet 9 inches) tall." },
  { id: 25, question: "In Massachusetts, when approaching a stopped school bus with flashing red lights, you must:", options: ["Slow to 10 mph", "Stop from all directions", "Stop only if on the same side", "Proceed with caution"], correct: 1, explanation: "In Massachusetts, all vehicles must stop for a school bus displaying flashing red lights, from all directions." },
  { id: 26, question: "In Massachusetts, the fine for texting while driving on a first offense is:", options: ["$50", "$100", "$250", "$500"], correct: 1, explanation: "Massachusetts imposes a $100 fine for a first offense of texting or using a handheld device while driving." },
  { id: 27, question: "In Massachusetts, at what age does a Junior Operator License convert to a full license?", options: ["17", "18", "19", "21"], correct: 1, explanation: "In Massachusetts, a Junior Operator License converts to a full license at age 18." },
  { id: 28, question: "In Massachusetts, the speed limit on unposted rural roads is:", options: ["30 mph", "35 mph", "40 mph", "45 mph"], correct: 0, explanation: "In Massachusetts, unposted roads outside thickly settled or business districts have a default speed limit of 30 mph for roads not meeting the criteria for higher limits. Many rural roads default to 30-50 mph depending on classification." },
  { id: 29, question: "In Massachusetts, you must have your headlights on:", options: ["Only after dark", "From 30 minutes after sunset to 30 minutes before sunrise and during poor visibility", "Only in rain", "At all times"], correct: 1, explanation: "Massachusetts requires headlights from 30 minutes after sunset to 30 minutes before sunrise and when visibility is less than 500 feet." },
  { id: 30, question: "In Massachusetts, a learner's permit holder must be accompanied by:", options: ["Any licensed driver", "A licensed driver 21 or older with at least 1 year of experience", "A parent only", "Any driver 18 or older"], correct: 1, explanation: "Massachusetts learner's permit holders must be accompanied by a licensed driver who is at least 21 years old and has at least one year of driving experience." },
  { id: 31, question: "In Massachusetts, what is the penalty for a second OUI offense?", options: ["Up to $5,000 fine, 60 days to 2.5 years in jail, 2-year license loss", "Up to $10,000 fine, 30 days to 2.5 years in jail, 2-year license loss", "$500 fine only", "Warning and community service"], correct: 1, explanation: "A second OUI in Massachusetts carries fines up to $10,000, 30 days to 2.5 years in jail, and a 2-year license suspension." },
  { id: 32, question: "In Massachusetts, what is required before a vehicle can be registered?", options: ["Safety inspection only", "Emissions inspection only", "Both a valid safety and emissions inspection", "No inspection required"], correct: 2, explanation: "Massachusetts requires annual vehicle safety and emissions inspections for registration." },
  { id: 33, question: "In Massachusetts, how far from a crosswalk must you stop?", options: ["10 feet", "15 feet", "20 feet", "25 feet"], correct: 2, explanation: "In Massachusetts, drivers must stop at least 20 feet from a crosswalk when yielding to pedestrians." },
  { id: 34, question: "In Massachusetts, passing a stopped school bus carries a fine of up to:", options: ["$100", "$250", "$500", "$1,000"], correct: 1, explanation: "Passing a stopped school bus in Massachusetts carries a fine of up to $250 for a first offense." },
  { id: 35, question: "In Massachusetts, what must a driver do when an emergency vehicle approaches with lights and sirens?", options: ["Speed up to clear the road", "Pull to the right and stop", "Stop immediately wherever you are", "Continue at the same speed"], correct: 1, explanation: "In Massachusetts, drivers must pull to the right side of the road and stop when an emergency vehicle approaches with lights and sirens." },
  { id: 36, question: "In Massachusetts, how long is the learner's permit valid?", options: ["6 months", "1 year", "2 years", "4 years"], correct: 2, explanation: "A Massachusetts learner's permit is valid for 2 years from the date of issue." },
  { id: 37, question: "In Massachusetts, it is illegal to leave a child under what age unattended in a vehicle?", options: ["6 years old", "8 years old", "10 years old", "12 years old"], correct: 3, explanation: "Massachusetts law prohibits leaving a child under 12 years old unattended in a motor vehicle." },
  { id: 38, question: "In Massachusetts, the speed limit on Route 128 and other major highways is typically:", options: ["50 mph", "55 mph", "60 mph", "65 mph"], correct: 1, explanation: "Major highways like Route 128 in Massachusetts typically have a 55 mph speed limit." },
  { id: 39, question: "In Massachusetts, what happens to a Junior Operator who commits a traffic violation?", options: ["Warning only", "License is suspended for 60 days on first offense", "Points are added", "Nothing for minor violations"], correct: 1, explanation: "A Massachusetts Junior Operator who commits a traffic violation has their license suspended for 60 days on the first offense." },
  { id: 40, question: "In Massachusetts, you may not park within how many feet of a fire hydrant?", options: ["5 feet", "10 feet", "15 feet", "20 feet"], correct: 1, explanation: "In Massachusetts, it is illegal to park within 10 feet of a fire hydrant." }
