  { id: 37, question: "In Utah, at an uncontrolled intersection, who has the right-of-way?", options: ["The vehicle on the left", "The vehicle on the right", "The faster vehicle", "The larger vehicle"], correct: 1, explanation: "At uncontrolled intersections in Utah, the vehicle on the right has the right-of-way." },
  { id: 38, question: "In Utah, the penalty for passing a stopped school bus is:", options: ["$100 fine", "$200 fine", "Up to $750 fine", "Warning for first offense"], correct: 2, explanation: "Passing a stopped school bus in Utah carries fines up to $750." },
  { id: 39, question: "In Utah, when passing a bicyclist, you must leave at least:", options: ["2 feet", "3 feet", "4 feet", "6 feet"], correct: 1, explanation: "Utah law requires at least 3 feet of clearance when passing a bicyclist." },
  { id: 40, question: "In Utah, which of the following is TRUE about the state's DUI law?", options: ["Utah's 0.05% BAC limit only applies to first-time offenders", "Utah's 0.05% BAC limit applies to all drivers 21 and over", "Utah uses 0.08% like all other states", "Utah's BAC limit is 0.05% but only enforced on highways"], correct: 1, explanation: "Utah's 0.05% BAC limit applies universally to all drivers 21 and over, making it the strictest DUI threshold in the nation." }
